-- ============================================================
-- bahar 演示环境 —— 常用基础数据（幂等，可重复执行）
--
-- 覆盖 4 个行业库: bahar-db / bahar-car / bahar-catering / bahar-health
-- 每个库写入: 业务配置 / 会员等级 / 演示会员 / 商品分类 / 商品服务 / 卡券 / 员工 / 轮播 / 打印机
--
-- 会员登录密码: 123456  算法: base64(MD5(password + salt))  salt = a1b2
--   密文 = sZbejahexJx8f1vB9Z/YiQ==   （MemberServiceImpl.verifyPassword 的 MD5 回退分支）
-- 说明:
--   1. 仅操作固定 ID 的演示记录，不触碰其它业务数据
--   2. 每次执行先按 ID 区间 DELETE 再 INSERT，可安全重跑
-- ============================================================


-- ############################################################
-- bahar-db  (通用零售 bahar)
-- ############################################################
USE `bahar-db`;

-- 清理本脚本产生的演示数据（固定 ID 1-9999 区间内的演示记录）
DELETE FROM mt_printer       WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_banner        WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_staff         WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_coupon        WHERE ID BETWEEN 1 AND 20;
DELETE FROM mt_coupon_group  WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_goods         WHERE ID BETWEEN 1 AND 50;
DELETE FROM mt_goods_cate    WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_user          WHERE ID BETWEEN 1 AND 100;
DELETE FROM mt_user_grade    WHERE ID BETWEEN 1 AND 10;
DELETE FROM mt_setting       WHERE ID BETWEEN 1 AND 50;

-- 1) 系统/业务配置

-- 2) 会员等级

-- 3) 演示会员（密码统一 123456，MD5 回退校验）

-- 4) 商品/服务分类

-- 5) 商品 / 服务项目

-- 6) 卡券


-- 7) 员工

-- 8) 首页轮播

-- 9) 打印机


