SELECT 'bahar-db' AS db_name, (SELECT COUNT(*) FROM `bahar-db`.mt_setting) AS setting_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_user_grade) AS grade_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_user) AS user_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_goods_cate) AS cate_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_goods) AS goods_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_coupon) AS coupon_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_staff) AS staff_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_banner) AS banner_rows, (SELECT COUNT(*) FROM `bahar-db`.mt_printer) AS printer_rows
UNION ALL
SELECT 'bahar-car' AS db_name, (SELECT COUNT(*) FROM `bahar-car`.mt_setting) AS setting_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_user_grade) AS grade_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_user) AS user_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_goods_cate) AS cate_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_goods) AS goods_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_coupon) AS coupon_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_staff) AS staff_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_banner) AS banner_rows, (SELECT COUNT(*) FROM `bahar-car`.mt_printer) AS printer_rows
UNION ALL
