UNION ALL
SELECT 'bahar-health' AS db_name, (SELECT COUNT(*) FROM `bahar-health`.mt_setting) AS setting_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_user_grade) AS grade_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_user) AS user_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_goods_cate) AS cate_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_goods) AS goods_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_coupon) AS coupon_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_staff) AS staff_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_banner) AS banner_rows, (SELECT COUNT(*) FROM `bahar-health`.mt_printer) AS printer_rows;